contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 amount) public {
        c.getTokens();
        uint256 bal0 = c.balanceOf(address(this));
        require(amount <= bal0);
        bool reverted;
        if (to == address(0)) {
            try c.transfer(to, amount) { reverted = false; } catch { reverted = true; }
            assert(reverted && c.balanceOf(address(this)) == bal0);
        } else {
            bool ok = c.transfer(to, amount);
            assert(ok && c.balanceOf(to) == amount && c.balanceOf(address(this)) == bal0 - amount);
        }
    }
    receive() external payable {}
}

