contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address to, uint256 amount) public {
        require(from != address(0));
        require(to != address(0));
        require(amount > 0);

        c.XBornID();

        c.transfer(from, amount);
        require(c.balanceOf(from) == amount);

        c.approve(address(this), amount);
        require(c.allowance(from, address(this)) == amount);

        uint256 fromBalBefore = c.balanceOf(from);
        uint256 toBalBefore = c.balanceOf(to);

        bool ok = c.transferFrom(from, to, amount);

        uint256 fromBalAfter = c.balanceOf(from);
        uint256 toBalAfter = c.balanceOf(to);
        uint256 allowAfter = c.allowance(from, address(this));

        assert(ok && fromBalAfter == fromBalBefore - amount && toBalAfter == toBalBefore + amount && allowAfter == amount - amount);
    }

    receive() external payable {}
}

